const VIEW = { full: '0 0 2002 679', mark: '0 0 852 866' }

export const BRAND_NAME = 'פרלשטיין'
export const BRAND_SUFFIX = 'משכנתאות'

export function Logo({
  variant = 'full',
  tone = 'dark',
  className,
  height = 32,
}: {
  variant?: 'full' | 'mark'
  /** `light` is for the dark sidebar: the navy wordmark is redrawn white. */
  tone?: 'light' | 'dark'
  className?: string
  height?: number
}) {
  if (variant === 'mark') {
    return (
      <svg
        viewBox={VIEW.mark}
        height={height}
        role="img"
        aria-label={`${BRAND_NAME} ${BRAND_SUFFIX}`}
        className={cn('w-auto', className)}
      >
        <path d={MARK} fill="#D2A64A" />
      </svg>
    )
  }

  return (
    <svg
      viewBox={VIEW.full}
      height={height}
      role="img"
      aria-label={`${BRAND_NAME} ${BRAND_SUFFIX}`}
      className={cn('w-auto', className)}
    >
      <path d={WORDMARK} fill={tone === 'light' ? '#FFFFFF' : '#0F365B'} />
      <path d={MARK_IN_LOGO} fill="#D2A64A" />
    </svg>
  )
}
